extra_head_css:
.svg-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .svg-sidebar { flex: 0 0 320px; display: flex; flex-direction: column; gap: 14px; }
    .svg-canvas-area { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .svg-workspace { flex-direction: column; } .svg-sidebar { flex: none; width: 100%; } }

    .input-tabs { display: flex; gap: 0; border-bottom: 1px solid var(--border-color); margin-bottom: 12px; }
    .input-tab {
      padding: 8px 16px; cursor: pointer; font-size: .82rem; color: var(--text-secondary);
      border-bottom: 2px solid transparent; transition: all .2s; background: none; border-top: none; border-left: none; border-right: none;
    }
    .input-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
    .input-tab:hover { color: var(--text-primary); }
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    .svg-code-area {
      width: 100%; min-height: 180px; padding: 10px; border: 1px solid var(--border-color);
      border-radius: 8px; background: var(--bg-primary); color: var(--text-primary);
      font-family: 'Fira Code', monospace; font-size: .8rem; resize: vertical;
    }

    .param-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
    .param-row label { font-size: .8rem; color: var(--text-secondary); min-width: 90px; }
    .param-row select, .param-row input[type="number"] {
      flex: 1; padding: 7px 10px; border: 1px solid var(--border-color); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .82rem;
    }

    .preview-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border-color); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 350px; overflow: auto;
    }
    .preview-wrapper canvas { max-width: 100%; max-height: 65vh; }

    .info-row { display: flex; gap: 12px; font-size: .8rem; color: var(--text-secondary); padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px; margin-top: 12px; }
    .info-row span { display: flex; align-items: center; gap: 4px; }
